    "evidence_audit": {
      "visible_facts": [
        "原图由上下两幅同一男性的半身肖像组成",
        "男性为短黑发，额前有自然垂落的发丝",
        "男性穿深色外套，内搭灰绿色上衣并配深色领带",
        "背景为明亮的户外虚化环境，整体具有柔和电影感",
        "上幅人物侧身回望镜头，下幅人物微微低头并带含蓄笑意"
      ],
      "anchor_features": [
        "张颂文本人可辨识的面部身份",
        "短黑发与额前碎发",
        "较窄长的脸型和细长眼部轮廓",
        "深色正式外套、灰绿色内层与深色领带的组合"
      ],
      "trigger_check": "能。提示词明确指定张颂文，且给出单人写实剧照语境，模型可据其公开形象召回身份与外观特征。",
      "counterexample_test": "尝试用泛化的中年男性替代主体；因不满足提示词明确指定的张颂文身份，无法构成合规反例。"
    },
    "gen_prompt": "现代中国电视剧的单人电影感剧照：张颂文站在开阔户外场景前，身体略侧并回望镜头，采用胸像至半身构图，背景城市与天空化成柔和散景，阴天自然光，冷灰与暖黄交织，写实克制，浅景深，完整单画面。",
    "implicit_checks": [
      {
        "check": "主体面部应保持张颂文本人可辨识的身份特征，而不是泛化为另一名中年男演员",
        "knowledge": "[solid] 知名演员的面部身份由稳定的脸型、眼部比例、鼻口关系与整体五官组合共同构成；指定演员时应呈现其本人而非随机同龄男性",
        "verified": true,
        "weight": 0.4,
        "rubric": {
          "0": "主体面部无法对应指定演员，呈现为随机中年男性或明显不同的公众人物",
          "1": "整体年龄和气质接近，但五官比例、脸型或眼部结构与指定演员差异明显",
          "2": "面部身份清晰对应指定演员，脸型、眼部、鼻口关系和整体神态具有一致性"
        },
        "acceptable_variants": [
          "轻微侧脸或自然表情变化下仍能辨认出指定演员",
          "局部被阴影或浅景深影响，但主要五官关系保持一致"
        ]
      },
      {
        "check": "主体保留短黑发、额前自然垂落发丝、较窄长脸型与细长眼部轮廓",
        "knowledge": "[solid] 样本人物的可见识别外观包括短黑发、额前碎发、偏窄长脸型和细长眼部轮廓；这些属于可直接视觉核验的形态特征",
        "verified": true,
        "weight": 0.3,
        "rubric": {
          "0": "发色或发长明显偏离，且脸型与眼部轮廓均无法对应样本人物",
          "1": "保留其中一至两项特征，但发型、脸型或眼部比例存在明显偏差",
          "2": "短黑发、额前碎发、窄长脸型和细长眼部轮廓均清楚呈现"
        },
        "acceptable_variants": [
          "侧分或轻微蓬松的短发，只要额前仍保留自然碎发",
          "正面、三分之二侧面或低头角度下呈现相同脸型与眼部比例"
        ]
      },
      {
        "check": "主体服装呈深色外套、灰绿色内层与深色领带的正式搭配",
        "knowledge": "[solid] 样本中可直接看到深色外套、灰绿色内层和深色领带三者的组合关系，属于稳定的服装锚点",
        "verified": true,
        "weight": 0.3,
        "rubric": {
          "0": "缺少正式外套或领带，且整体服装颜色与样本组合完全不同",
          "1": "保留正式外套和领带，但内层颜色或外套深浅与样本明显不符",
          "2": "深色外套、灰绿色内层和深色领带三项均清晰可见，搭配关系正确"
        },
        "acceptable_variants": [
          "外套因光线呈黑色、深蓝或深灰，只要整体保持深色",
          "领带被轻微遮挡，但衣领、结位和主要颜色关系仍可判断"
        ]
      }
    ],
    "facet_tags": [
      "character_likeness",
      "subject_prominence",
      "lighting_atmosphere",
      "style_control"
    ],
    "gate_spec": {
      "required_subjects": [
        "张颂文"
      ],
      "theme_definition": "以张颂文为唯一主体的写实中国电视剧户外肖像剧照"
    },
    "expected_failure_modes": [
      "将指定演员画成泛化的中年男性，面部身份不可辨认",
      "错误生成过长或明显卷曲的发型，脸型和眼部比例偏离样本人物",
      "把正式搭配改成休闲服、白色内层或无领带造型"
    ],
    "notes": "利用张颂文的公众面部身份与样本中的发型、服装锚点，测试模型能否在不同单幅户外场景中保持人物一致性。"
  }
